template<class T,class S,class CT>int probe(int mode){const int n=16;T*A,*B;S*C;allocate_memory(n,n,n,&A,&B,&C);for(int i=0;i<n*n;i++){A[i]=cast<T>(i/16==i%16?1:0);B[i]=cast<T>(i/16==i%16?1:0);C[i]=cast<S>(0);}A[0]=cast<T>(1);A[1]=cast<T>(2);A[16]=cast<T>(3);A[17]=cast<T>(4);B[0]=cast<T>(5);B[1]=cast<T>(6);B[16]=cast<T>(7);B[17]=cast<T>(8);CT alpha=cast<CT>(1),beta=cast<CT>(0);bool ok=cublasLt_gemm(n,n,n,B,A,C,n,n,n,&alpha,&beta,mode);printf("SOURCE_PROBE {\"algorithm_found\":%s,\"raw_C_2x2\":[%.17g,%.17g,%.17g,%.17g],\"declared_AB\":[19,22,43,50],\"reversed_BA\":[23,34,31,46]}\n",ok?"true":"false",double(C[0]),double(C[1]),double(C[16]),double(C[17]));free_memory(A,B,C);return ok?0:10;}
int main(int argc,char**argv){if(argc!=2)return 1;auto lib=dlopen("libcublasLt.so.12",RTLD_NOW);auto sym=dlsym(lib,"cublasLtMatmul");Dl_info info{};if(!sym||!dladdr(sym,&info))return 2;printf("CUBLASLT_PROVENANCE version=%zu path=%s\n",cublasLtGetVersion(),info.dli_fname);cublasCheck(cublasLtCreate(&handle));cudaMalloc(&cublaslt_workspace,cublaslt_workspace_size);switch(atoi(argv[1])){case 0:return probe<double,double,double>(0);case 1:return probe<float,float,float>(0);case 2:return probe<float,float,float>(1);case 3:return probe<float,float,float>(2);case 4:return probe<float,float,float>(3);case 5:return probe<__half,__half,__half>(0);case 6:return probe<__half,__half,float>(0);case 7:return probe<__nv_bfloat16,__nv_bfloat16,float>(0);case 8:return probe<int8_t,int32_t,int32_t>(0);}return 3;}
